int create_virtio_gpu_object(struct virtio_gpu_device *vgdev, unsigned long size, bool kernel, bool pinned, struct virtio_gpu_object **bo_ptr) {
    struct virtio_gpu_object *bo = NULL;
    size_t obj_size = 0;

    if (!vgdev || !bo_ptr) {
        return -EINVAL;
    }

    if (size == 0) {
        return -EINVAL;
    }

    /* Determine the object type based on the kernel flag */
    if (kernel) {
        obj_size = sizeof(struct virtio_gpu_object_kernel);
    } else {
        obj_size = sizeof(struct virtio_gpu_object_user);
    }

    /* Allocate memory for the GPU object */
    bo = (struct virtio_gpu_object *)malloc(obj_size);
    if (!bo) {
        return -ENOMEM;
    }

    /* Initialize the GPU object */
    if (kernel) {
        struct virtio_gpu_object_kernel *kbo = (struct virtio_gpu_object_kernel *)bo;
        kbo->base.size = size;
        kbo->base.pinned = pinned;
        kbo->base.kernel = kernel;
        kbo->base.vgdev = vgdev;
        kbo->base.placement = VIRTIO_GPU_PLACEMENT_KERNEL;
    } else {
        struct virtio_gpu_object_user *ubo = (struct virtio_gpu_object_user *)bo;
        ubo->base.size = size;
        ubo->base.pinned = pinned;
        ubo->base.kernel = kernel;
        ubo->base.vgdev = vgdev;
        ubo->base.placement = VIRTIO_GPU_PLACEMENT_USER;
    }

    /* Assign the created object to the provided pointer */
    *bo_ptr = bo;

    return 0;
}
